// tg — Тоҷикӣ (tajique).
//
// A chave é o TEXTO EM PORTUGUÊS, exatamente como aparece no código. O que faltar aqui aparece em
// português, e não como tela vazia.
//
// POR QUE ENTROU: é a língua do Estado no TAJIQUISTÃO (Constituição, art. 2), e o Tajiquistão era um dos
// membros da ONU que nenhuma língua do Syden alcançava.
//
// É O PERSA, EM CIRÍLICO. A gramática e quase todo o vocabulário de base são os do fa.ts, mas escritos
// com o alfabeto de 1940 (com ғ, ӣ, қ, ӯ, ҳ, ҷ), da ESQUERDA para a DIREITA e com algarismos LATINOS — o
// contrário do persa, que escreve ۱۲۳. E a técnica vem do russo, como se fala lá: компютер, сервер,
// файл, браузер, интернет, экран.
//
// CONFIANÇA: BOA, NÃO ALTA. A gramática e o tratamento estão certos; o risco é uma palavra soar "persa do
// Irã" onde o tajique usa outra. Quem ler tajique e achar uma assim, a troca é de uma linha.
//
// TOM: **шумо**, pelo mesmo motivo do fa.ts: *ту* é de intimidade e, com quem acabou de chegar, soa
// atrevido, não próximo. *Шумо* é o neutro entre adultos e é o que os aplicativos usam.
//
// GÊNERO: NÃO HÁ. Como o persa, o tajique não tem gênero gramatical nem pronome que diga o sexo (*ӯ* é
// "ele" e "ela").
//
// PLURAL: depois de número, o substantivo fica no SINGULAR ("5 паём", "15 аъзо") — a forma é sempre a
// certa, qualquer que seja o número.
//
// {nome}: o tajique liga substantivo e nome pela IZAFE (-и): "анҷумани {comunidade}". O nome vem depois
// da izafe, e nada se cola nele.
//
// NÚMEROS: `Intl.NumberFormat('tg')` devolve `1 234 567` — latinos, com espaço.
//
// VOCABULÁRIO, decidido uma vez: comunidade = анҷуман (o انجمن do fa.ts), canal = канал, sala de voz =
// ҳуҷраи овозӣ, chamada = занг, conversa = сӯҳбат, mensagem = паём, senha = рамз, lixeira = сабад,
// tópico = ришта, conta = ҳисоб, administrador = маъмур, dono = соҳиб, cargo = нақш, convite = даъват,
// perfil = профил, transmissão = пахш, tela = экран, membro = аъзо, pacote = баста, enquete = пурсиш,
// denúncia = шикоят, notificação = огоҳинома, vila = деҳа, guarda-roupa = ҷевон, cutucada = ангуштзанӣ,
// recado (da tela de boas-vindas e do aviso) = эълон.
//
// SOM E VOZ SÃO DUAS PALAVRAS: овоз é a voz, садо é o som de soundboard e de aviso.
//
// SELO E INSÍGNIA SEPARADOS: selo = мӯҳр (o da comunidade), insígnia = нишон (a da pessoa).

