  'Deixe o título e o recado em branco para desmontar a tela: a comunidade volta a abrir direto nos canais.':
    'Сарлавҳа ва эълонро холӣ гузоред, то экран бардошта шавад: анҷуман боз мустақиман дар каналҳо кушода мешавад.',
