  'Nome de exibição': 'Номи намоишӣ',
  'É o nome que todos veem no Syden. Para entrar e nas menções com @, continua valendo o nome da conta.': 'Ин номест, ки ҳама дар Syden мебинанд. Барои воридшавӣ ва ёдоварӣ бо @ ҳамоно номи ҳисоб амал мекунад.',
  'Cargo': 'Нақш',
  'Mover para': 'Интиқол ба',
  'Desbloqueado': 'Кушода шуд',
  'Desbloquear': 'Аз басташавӣ баровардан',
  'Descartar': 'Партофтан',
  'Desconecta o Syden em todos os outros computadores e celulares. Você continua conectado aqui.':
    'Syden-ро дар ҳамаи компютерҳо ва телефонҳои дигар хомӯш мекунад. Ин ҷо ворид будан боқӣ мемонад.',
  'Desconectando…': 'Ҷудо мешавад…',
  'Desconectar': 'Ҷудо кардан',
  'Descrição': 'Тавсиф',
  'Desligado, a transmissão de quem está na sala aparece como convite e só começa a ser baixada quando você clica em Assistir. Isso poupa internet e processador — principalmente em sala cheia.':
    'Вақте ки хомӯш аст, пахши касоне, ки дар ҳуҷраанд, ҳамчун даъват намоён мешавад ва танҳо вақте боргирӣ мешавад, ки шумо Тамошоро пахш кунед. Ин интернет ва протсессорро сарфа мекунад — хусусан дар ҳуҷраи пур.',
  'Desligar câmera': 'Хомӯш кардани камера',
  'Deste servidor': 'Аз ин сервер',
  'Diga o e-mail da sua conta e mandamos um link para escolher outra.':
    'Почтаи электронии ҳисоби худро нависед, ва мо пайванд барои интихоби рамзи нав мефиристем.',
  'Digite sua senha para confirmar': 'Барои тасдиқ рамзи худро ворид кунед',
  'Disponível': 'Дастрас',
  'Do laranja ao vermelho, como carvão aceso.': 'Аз норанҷӣ то сурх, мисли ангишти фурӯзон.',
  'Dois emojis com o mesmo nome: cada um precisa do seu.': 'Ду эмоҷи бо як ном: ҳар кадом номи худро бояд дошта бошад.',
  'Dono': 'Соҳиб',
  'Dono da comunidade': 'Соҳиби анҷуман',
  'Dourado com brilho que passa devagar.': 'Тиллоӣ бо дурахше, ки оҳиста мегузарад.',
  'Durante uma chamada, esse botão toca estes sons para todos na sala. Instale pacotes prontos ou envie os seus; o que é seu favorito fica na frente do painel.':
    'Ҳангоми занг ин тугма ин садоҳоро барои ҳама дар ҳуҷра менавозад. Бастаҳои тайёрро насб кунед ё садоҳои худро бор кунед; дӯстдоштаҳои шумо дар пеши лавҳа меистанд.',
  'É a primeira coisa que alguém vê ao entrar na comunidade, uma vez só. Sem isto, a pessoa cai direto na lista de canais.':
    'Ин аввалин чизест, ки касе ҳангоми ворид шудан ба анҷуман мебинад, танҳо як бор. Бе он, шахс мустақиман ба рӯйхати каналҳо меравад.',
  'É assim que os outros veem você na lista e nas conversas.': 'Дигарон шуморо дар рӯйхат ва сӯҳбатҳо ҳамин тавр мебинанд.',
  'É isto que os seus amigos veem aqui embaixo do quarto. O que eles escreverem chega para você como conversa privada, com 💡 na frente — e o Syden já responde agradecendo na hora. Quando a ideia entrar no app, use o joinha na mensagem: do lado deles cai confete e a medalha aparece no perfil.':
    'Дӯстони шумо ин ҷо, дар зери ҳуҷра, инро мебинанд. Он чи онҳо менависанд, ба шумо ҳамчун сӯҳбати хусусӣ бо 💡 дар пеш мерасад — ва Syden фавран бо ташаккур ҷавоб медиҳад. Вақте ки ғоя ба барнома ворид шавад, ба паём 👍 гузоред: дар тарафи онҳо конфетти мерезад ва медал дар профил пайдо мешавад.',
  'é o que você está enviando': 'чизест, ки шумо мефиристед',
  'É o seu único jeito de entrar. Defina uma senha antes de desligar.': 'Ин ягона роҳи вуруди шумост. Пеш аз ҷудо кардан рамз муқаррар кунед.',
  'E-mail': 'Почтаи электронӣ',
  'Eco de lugar grande e vazio.': 'Акси садои ҷои калон ва холӣ.',
  'Efeito do nome': 'Эффекти ном',
