  'Endereço guardado. Confira a sua caixa de entrada para confirmar.': 'Суроға нигоҳ дошта шуд. Барои тасдиқ қуттии воридотии худро санҷед.',
  'Endereço guardado. O envio de e-mail ainda não está ligado neste servidor, então o link de confirmação ficou no registro do servidor.':
    'Суроға нигоҳ дошта шуд. Фиристодани почтаи электронӣ дар ин сервер ҳанӯз фаъол нест, бинобар ин пайванди тасдиқ дар сабти сервер монд.',
  'Enfeites, sons e emojis': 'Ороишҳо, садоҳо ва эмоҷиҳо',
  'Enquanto isto aparecer, os números abaixo não existem —': 'То вақте ки ин намоён аст, рақамҳои поён вуҷуд надоранд —',
