  'Aniversário': 'Зодрӯз',
  'Aniversários': 'Зодрӯзҳо',
  'Canal dos parabéns': 'Канали табрикҳо',
  'Dia': 'Рӯз',
  'Hoje é aniversário de {pessoa}! 🎉 Parabéns!': 'Имрӯз зодрӯзи {pessoa} аст! 🎉 Зодрӯз муборак!',
  'Mês': 'Моҳ',
  'No dia do aniversário de quem informou a data, o Syden publica os parabéns no canal escolhido. Use {pessoa} no lugar do nome.': 'Дар зодрӯзи касе, ки санаашро ворид кардааст, Syden дар канали интихобшуда табрик нашр мекунад. Ба ҷои ном {pessoa}-ро истифода баред.',
  'Só o dia e o mês, nunca o ano. As comunidades que avisam aniversários dão os parabéns no dia. É opcional, e dá para apagar quando quiser.': 'Танҳо рӯз ва моҳ, ҳеҷ гоҳ сол. Ҷомеаҳое, ки зодрӯзҳоро эълон мекунанд, ҳамон рӯз табрик мегӯянд. Ихтиёрӣ аст ва ҳар вақт метавонед нест кунед.',
  'Texto dos parabéns': 'Матни табрик',
  'Agendar': 'Ба нақша гирифтан',
  'Apagar a mensagem agendada': 'Нест кардани паёми ба нақша гирифташуда',
  'Canal': 'Канал',
  'Combinado: lembro você em {tempo}.': 'Хуб: пас аз {tempo} хотиррасон мекунам.',
