  'Mensagens agendadas': 'Паёмҳои ба нақша гирифташуда',
  'Na hora marcada, o Syden publica o texto no canal. Dá para repetir todo dia ou toda semana.': 'Дар вақти муайян Syden матнро дар канал нашр мекунад. Метавонад ҳар рӯз ё ҳар ҳафта такрор шавад.',
  'Nova mensagem agendada': 'Паёми нави ба нақша',
