  'Toda semana': 'Ҳар ҳафта',
  'Todo dia': 'Ҳар рӯз',
  'Uma vez': 'Як бор',
  'Alguém escreve o comando no começo de uma mensagem, como !regras, e o Syden responde no canal com o texto que você cadastrar. Use {pessoa} para o nome de quem pediu e {comunidade} para o nome da comunidade.': 'Касе дар аввали паём фармон менависад, масалан !regras, ва Syden дар канал бо матне, ки шумо ворид кардед, ҷавоб медиҳад. Барои номи пурсанда {pessoa} ва барои номи ҷомеа {comunidade}-ро истифода баред.',
