  'Palavras proibidas': 'Калимаҳои манъшуда',
  'Quanto tempo cada pessoa espera entre uma mensagem e outra no canal.': 'Ҳар кас дар канал байни паёмҳо чӣ қадар интизор мешавад.',
  'Regras': 'Қоидаҳо',
  'Regras que o Syden aplica sozinho, antes de a mensagem aparecer. Quem administra não passa por elas. A mensagem barrada volta para quem escreveu, com o motivo, e ninguém mais a vê.': 'Қоидаҳое, ки Syden худаш пеш аз пайдо шудани паём татбиқ мекунад. Ба маъмурон дахл надоранд. Паёми басташуда бо сабабаш ба нависанда бармегардад ва каси дигар онро намебинад.',
  'Salvo.': 'Захира шуд.',
  'Uma por linha. Vale a palavra inteira, sem diferença de acento ou de maiúscula: proibir uma palavra não barra outra mais longa que só a contenha.': 'Дар ҳар сатр як. Калимаи пурра ҳисоб мешавад, бе фарқи аломатҳо ё ҳарфҳои калон: манъ кардани калима калимаи дарозтареро, ки онро танҳо дар бар мегирад, намебандад.',
