  'Adicionar recompensa': 'Илова кардани мукофот',
  'Cada mensagem vale pontos (uma por minuto), e cada minuto numa sala com mais alguém também. Quem sobe de nível recebe um aviso só para si.': 'Ҳар паём хол медиҳад (дар як дақиқа як), ҳамчунин ҳар дақиқа дар ҳуҷра бо каси дигар. Касе, ки сатҳаш баланд шуд, огоҳиро танҳо барои худ мегирад.',
  'Cargo da recompensa': 'Нақши мукофот',
