  'O selo aparece aqui quando o primeiro marco cair. Até lá ele fica guardado — e chegar nele é justamente o que ele vai significar.':
    'Мӯҳр вақте ин ҷо пайдо мешавад, ки марҳилаи аввал ба даст ояд. То он вақт пинҳон аст — ва расидан ба он маҳз ҳамон чизест, ки он маъно хоҳад дошт.',
  'O selo desta comunidade é': 'Мӯҳри ин анҷуман:',
  'O servidor demorou demais para responder. Tente de novo.': 'Сервер барои ҷавоб аз ҳад зиёд вақт гирифт. Боз кӯшиш кунед.',
  'O som chega quando você abre esta transmissão.': 'Садо вақте мерасад, ки шумо ин пахшро кушоед.',
  'O survival do Léo': 'Survival-и Фирӯз',
  'O Syden já sabe escrever em qualquer uma destas línguas — falta a tradução dos textos. Enquanto ela não chega, o que não estiver traduzido aparece em português, e as letras de cada alfabeto aparecem certas, sem quadradinhos.':
    'Syden аллакай метавонад бо ҳар яке аз ин забонҳо нависад — танҳо тарҷумаи матнҳо намерасад. То он вақт, он чи тарҷума нашудааст, ба португалӣ намоён мешавад ва ҳарфҳои ҳар алифбо дуруст, бе чоркунҷаҳо, намоён мешаванд.',
