  'Sua senha, para confirmar que é você': 'Рамзи шумо, барои тасдиқ, ки ин шумоед',
  'Sua transmissão está sem som. O navegador só manda o som se você marcar “compartilhar áudio” na janelinha de escolher a tela.':
    'Пахши шумо садо надорад. Браузер садоро танҳо вақте мефиристад, ки шумо дар равзанаи интихоби экран «мубодилаи садо»-ро қайд кунед.',
  'Sua voz': 'Овози шумо',
  'Suba músicas que você já tem. Um arquivo': 'Сурудҳоеро, ки аллакай доред, бор кунед. Файли',
  'Suba só o que é seu ou o que você tem direito de usar. Ter o arquivo não é o mesmo que ter direito de tocar para outras pessoas.':
    'Танҳо он чиро бор кунед, ки аз они шумост ё ҳуқуқи истифодаашро доред. Доштани файл маънои ҳуқуқи навохтани онро барои дигарон надорад.',
  'Sugestões de melhoria': 'Пешниҳодҳо барои беҳбудӣ',
  'Supressão de ruído': 'Пахш кардани садои зиёдатӣ',
  'Tamanho do texto': 'Андозаи матн',
  'Também dá para arrastar a borda de cada barra na tela. Dois cliques na borda volta ao padrão.':
    'Канори ҳар панелро низ мустақиман дар экран кашидан мумкин аст. Ду клик дар канор ба ҳолати пешфарз бармегардонад.',
  'Também dá para colar o endereço de um GIF ou de uma imagem. O Syden baixa uma cópia e guarda: se o endereço sair do ar depois, a capa continua.':
    'Суроғаи GIF ё тасвирро низ гузоштан мумкин аст. Syden нусхаеро боргирӣ ва нигоҳ медорад: агар баъдтар суроға аз кор монад, муқова боқӣ мемонад.',
  'Também de graça, e também trocáveis quando quiser. Ficam nas configurações da comunidade, porque valem para a comunidade inteira e não só para você.':
    'Инҳо низ ройгонанд ва ҳар вақт иваз кардан мумкин аст. Онҳо дар танзимоти анҷуман ҷойгиранд, зеро барои тамоми анҷуман амал мекунанд, на танҳо барои шумо.',
