  'Toca um som quando alguém entra ou sai da sua sala, quando alguém começa a compartilhar a tela e quando você silencia ou ensurdece.':
    'Вақте ки касе ба ҳуҷраи шумо ворид мешавад ё мебарояд, вақте ки касе мубодилаи экранро оғоз мекунад ва вақте ки шумо микрофон ё садоро хомӯш мекунед, садо менавозад.',
  'Tocando…': 'Навохта мешавад…',
  'Toda letra com a mesma largura.': 'Ҳамаи ҳарфҳо бо паҳнии якхела.',
  'Todas as cores girando devagar. A mais chamativa de todas.': 'Ҳамаи рангҳо оҳиста давр мезананд. Аз ҳама чашмгиртар.',
  'Todo mundo desta comunidade pode usar estes emojis escrevendo {exemplo} ou pelo botão de emoji do chat. Sem assinatura: está tudo liberado.':
    'Ҳар кас дар ин анҷуман метавонад ин эмоҷиҳоро бо навиштани {exemplo} ё тавассути тугмаи эмоҷии чат истифода барад. Бе обуна: ҳама чиз озод аст.',
  'Tom mais alto e mais claro.': 'Оҳанги баландтар ва равшантар.',
