  'Um halo discreto na cor do próprio nome.': 'Ҳалаи ором ба ранги худи ном.',
  'Um lugar novo, com canais próprios, e você decide quem entra.': 'Ҷои нав бо каналҳои худ, ва шумо ҳал мекунед, ки кӣ ворид шавад.',
  'Um lugar novo, com canais próprios. Você escolhe quem entra pelo código de convite.':
    'Ҷои нав бо каналҳои худ. Шумо бо рамзи даъват интихоб мекунед, ки кӣ ворид шавад.',
  'Um pacote instalado entra para toda a comunidade: os emojis dele passam a valer nas mensagens de todo mundo.':
    'Бастаи насбшуда барои тамоми анҷуман амал мекунад: эмоҷиҳои он дар паёмҳои ҳама кор мекунанд.',
  'Uma cópia do que você escreveu fica 90 dias fora do app, para o caso de pedido de autoridade. Ninguém a lê pelo Syden.':
    'Нусхаи он чи шумо навиштаед, 90 рӯз берун аз барнома нигоҳ дошта мешавад, барои ҳолати дархости мақомот. Ҳеҷ кас онро тавассути Syden намехонад.',
  'Uma ideia sua entrou no Syden': 'Як ғояи шумо ба Syden ворид шуд',
  'Uma imagem larga, de 1200 por 300 ou parecida. GIF animado vale, e anima de verdade. Sem capa, fica a arte que você escolheu nas boas-vindas.':
    'Тасвири паҳн, 1200 ба 300 ё монанди он. GIF-и ҳаракатнок ҳам мешавад ва воқеан ҳаракат мекунад. Бе муқова, расме, ки барои хушомадгӯӣ интихоб кардаед, мемонад.',
  'Uma regra ou aviso por linha: o coelho de quem chega lê um por um.':
    'Дар ҳар сатр як қоида ё эълон: харгӯши навомада онҳоро як-як мехонад.',
