  'Você ainda não tem nenhuma. Elas chegam como presente ou como recompensa — por exemplo, quando uma ideia sua entra no Syden.':
    'Шумо ҳанӯз ягонто надоред. Онҳо ҳамчун тӯҳфа ё мукофот меоянд — масалан, вақте ки ғояи шумо ба Syden ворид мешавад.',
  'Você chegou no começo de tudo. Obrigado por estar aqui desde quando isto era só uma ideia entre amigos.':
    'Шумо дар оғози ҳама чиз омадед. Ташаккур, ки аз замоне ин ҷоед, ки ин танҳо як ғоя байни дӯстон буд.',
  'Você entrou por um serviço de fora e ainda não tem senha nesta conta. Defina uma aqui: passa a valer como segundo jeito de entrar, e é o que permite desligar aquele serviço depois.':
    'Шумо тавассути хидмати берунӣ ворид шудед ва ин ҳисоб ҳанӯз рамз надорад. Онро ин ҷо муқаррар кунед: он роҳи дуюми вуруд мешавад ва ба шумо имкон медиҳад, ки баъдтар он хидматро ҷудо кунед.',
  'Você está silenciado!': 'Микрофони шумо хомӯш аст!',
  'Você foi convidado. É só escolher um nome, um e-mail e uma senha.': 'Шумо даъват шудед. Танҳо ном, почтаи электронӣ ва рамзро интихоб кунед.',
  'Você não bloqueou ninguém.': 'Шумо касеро манъ накардаед.',
