  'Ao lado de um objeto de tamanho conhecido aparece outro, e cada um aumenta ou diminui esse outro até achar o tamanho certo. Quem chegar mais perto ganha mais pontos.': 'Дар паҳлӯи ашёи андозаи маълум ашёи дигар пайдо мешавад ва ҳар кас онро калон ё хурд мекунад, то андозаи дурустро ёбад. Касе, ки наздиктар шавад, холи бештар мегирад.',
