  'Outros jogos': 'Бозиҳои дигар',
  'Stop': 'Стоп',
  'Sai uma letra e cada um escreve uma palavra com ela em cada categoria. Quem completar primeiro aperta STOP, e a turma decide o que vale.': 'Як ҳарф мебарояд ва ҳар кас дар ҳар категория калимае бо он менависад. Касе ки аввал тамом кунад, СТОП-ро пахш мекунад ва дӯстон қарор медиҳанд, ки чӣ ҳисоб мешавад.',
  'Sudoku': 'Судоку',
  'Todo mundo recebe o mesmo sudoku, e a sala vê quem está mais perto de terminar.': 'Ҳама як судоку мегиранд ва ҳуҷра мебинад, ки кӣ ба анҷом наздиктар аст.',
  'Cinco em linha': 'Панҷ дар як қатор',
  'Duas pessoas põem pedras no tabuleiro, uma de cada vez. Vence quem fizer cinco seguidas. A sala assiste.': 'Ду нафар навбат ба навбат ба тахта санг мегузоранд. Касе ки панҷ сангро пайдарпай гузорад, ғолиб мешавад. Ҳуҷра тамошо мекунад.',
  'Mancala': 'Манкала',
  'O jogo de semear: pegue as sementes de uma casa e espalhe uma por casa. Vence quem guardar mais no depósito. A sala assiste.': 'Бозии коштан: тухмиҳоро аз як чуқурча гирифта, ба ҳар чуқурча яктогӣ гузоред. Касе ки дар анбораш бештар ҷамъ кунад, ғолиб мешавад. Ҳуҷра тамошо мекунад.',
