  'Jogo desconhecido.': 'Бозии номаълум.',
  'Entre na sala de voz para jogar com a turma.': 'Барои бо дӯстон бозӣ кардан ба ҳуҷраи овозӣ ворид шавед.',
  'Já tem uma partida acontecendo nesta sala.': 'Дар ин ҳуҷра аллакай бозӣ идома дорад.',
  'Só quem começou a partida pode encerrá-la antes do fim.': 'Танҳо касе, ки бозиро оғоз кардааст, метавонад онро пеш аз охир қатъ кунад.',
  'Lobisomem': 'Гургодам',
  'À noite, escolha com os outros lobisomens quem atacar. De dia, não deixe ninguém desconfiar.': 'Шабона бо дигар гургодамон интихоб кунед, ки ба кӣ ҳамла кунед. Рӯзона нагузоред, ки касе шубҳа кунад.',
  'Vidente': 'Пешгӯ',
  'À noite, descubra se alguém é lobisomem. Conte de dia, se achar que vale o risco.': 'Шабона фаҳмед, ки оё касе гургодам аст. Агар арзад, рӯзона бигӯед.',
  'Anjo': 'Фаришта',
  'À noite, escolha alguém para proteger. Se os lobisomens atacarem essa pessoa, ela sobrevive.': 'Шабона касеро барои ҳимоя интихоб кунед. Агар гургодамон ба ҳамон кас ҳамла кунанд, ӯ зинда мемонад.',
  'Da vila': 'Аз деҳа',
  'À noite, durma. De dia, descubra quem são os lobisomens e vote para tirá-los do jogo.': 'Шабона хобед. Рӯзона фаҳмед, ки гургодамон киҳоянд, ва барои аз бозӣ баровардани онҳо овоз диҳед.',
  'A vila venceu!': 'Деҳа ғолиб омад!',
  'Os lobisomens venceram!': 'Гургодамон ғолиб омаданд!',
  'Noite {n}. A vila dorme.': 'Шаби {n}. Деҳа хоб аст.',
  'Os lobisomens atacaram {nome} durante a noite.': 'Шабона гургодамон ба {nome} ҳамла карданд.',
  'Ninguém morreu esta noite.': 'Имшаб касе намурд.',
  'Dia {n}. Conversem e votem em quem vocês acham que é lobisomem.': 'Рӯзи {n}. Сӯҳбат кунед ва ба касе овоз диҳед, ки ба фикратон гургодам аст.',
  'A vila tirou {nome} do jogo.': 'Деҳа {nome}-ро аз бозӣ баровард.',
  'Empate: ninguém sai hoje.': 'Баробар: имрӯз касе намебарояд.',
  'Clique em quem os lobisomens vão atacar.': 'Касеро клик кунед, ки гургодамон ба ӯ ҳамла мекунанд.',
  'Você já usou a sua visão esta noite.': 'Шумо имшаб аллакай аз биниши худ истифода бурдед.',
  'Clique em alguém para descobrir se é lobisomem.': 'Ба касе клик кунед, то бифаҳмед, ки гургодам аст ё не.',
  'Clique em quem você quer proteger esta noite.': 'Касеро клик кунед, ки мехоҳед имшаб ҳимоя кунед.',
  'Durma. Os outros papéis estão agindo.': 'Хобед. Нақшҳои дигар амал мекунанд.',
  'Você saiu do jogo. Agora só assiste — sem contar nada!': 'Шумо аз бозӣ баромадед. Акнун танҳо тамошо кунед — ҳеҷ чиз нагӯед!',
  'Clique em quem você quer tirar do jogo. O mais votado sai; empate, ninguém.': 'Касеро клик кунед, ки мехоҳед аз бозӣ бароред. Касе, ки бештар овоз гирад, мебарояд; ҳангоми баробарӣ ҳеҷ кас.',
  'é lobisomem': 'гургодам аст',
  'não é lobisomem': 'гургодам нест',
  'Ninguém hoje': 'Имрӯз ҳеҷ кас',
  'A solução do problema.': 'Ҳалли масъала.',
  'Acertou! Agora é torcer pelos outros.': 'Дуруст! Акнун дигаронро дастгирӣ кунед.',
  'Esse não era o lance. Espere a solução.': 'Ин гашт набуд. Ҳаллро интизор шавед.',
  'Você joga com as brancas. Ache o melhor lance.': 'Шумо бо сафедҳо бозӣ мекунед. Беҳтарин гаштро ёбед.',
  'Você joga com as pretas. Ache o melhor lance.': 'Шумо бо сиёҳҳо бозӣ мекунед. Беҳтарин гаштро ёбед.',
  'Ver este problema no Lichess': 'Ин масъаларо дар Lichess бинед',
  'Problema do Lichess · nota {nota}': 'Масъалаи Lichess · рейтинг {nota}',
  'Cada um recebe um papel em segredo. À noite os lobisomens atacam; de dia a vila conversa e vota em quem tirar do jogo. Precisa de 4 pessoas ou mais.': 'Ҳар кас пинҳонӣ нақш мегирад. Шабона гургодамон ҳамла мекунанд; рӯзона деҳа сӯҳбат карда, овоз медиҳад, ки киро аз бозӣ барорад. 4 нафар ё бештар лозим аст.',
  'Problemas de xadrez': 'Масъалаҳои шоҳмот',
  'Todo mundo recebe o mesmo problema do Lichess. Quem achar o lance certo mais rápido ganha o ponto extra.': 'Ҳама як масъалаи Lichess-ро мегиранд. Касе, ки гашти дурустро тезтар ёбад, холи иловагӣ мегирад.',
  'Os problemas de xadrez não estão no servidor.': 'Масъалаҳои шоҳмот дар сервер нестанд.',
  'Este problema já acabou.': 'Ин масъала аллакай тамом шуд.',
  'Lance inválido.': 'Гашти нодуруст.',
  'Solo': 'Танҳо',
  'Coletivo': 'Якҷоя',
  'Palavra secreta': 'Калимаи пинҳонӣ',
  'Todo mundo tenta adivinhar a mesma palavra de 5 letras, em 6 chutes. A sala vê as cores dos outros, mas não as letras. Quem acertar com menos chutes ganha mais pontos.': 'Ҳама кӯшиш мекунанд, ки як калимаи 5-ҳарфаро дар 6 кӯшиш ёбанд. Шумо рангҳои дигаронро мебинед, вале ҳарфҳояшонро не. Ҳар кӣ бо кӯшиши камтар ёбад, холи бештар мегирад.',
  'A palavra era: {palavra}': 'Калима ин буд: {palavra}',
  'Acabaram os seus chutes. Espere a palavra.': 'Кӯшишҳои шумо тамом шуданд. Калимаро интизор шавед.',
  'Escreva uma palavra de 5 letras e aperte Enter.': 'Калимаи 5-ҳарфа нависед ва Enter-ро пахш кунед.',
  'Seu quadro': 'Тахтаи шумо',
  'Escreva uma palavra de 5 letras.': 'Калимаи 5-ҳарфа нависед.',
  'Essa palavra não está na lista.': 'Ин калима дар рӯйхат нест.',
