  'Crie os cargos da comunidade primeiro, em Membros. Depois volte aqui para entregá-los sozinhos.': 'Аввал нақшҳои анҷуманро дар бахши Аъзоён эҷод кунед. Баъд ба ин ҷо баргардед, то онҳо худ ба худ дода шаванд.',
  'Cargo de quem entra': 'Нақшҳои воридшавандагон',
  'Toda pessoa nova recebe estes cargos ao entrar na comunidade.': 'Ҳар шахси нав ҳангоми ворид шудан ба анҷуман ин нақшҳоро мегирад.',
  'Cargos por reação': 'Нақшҳо бо вокуниш',
  'O Syden publica uma mensagem no canal com um emoji para cada cargo. Quem reage ganha o cargo; quem tira a reação, perde.': 'Syden дар канал паёме бо як эмоҷӣ барои ҳар нақш нашр мекунад. Касе ки вокуниш гузорад, нақшро мегирад; касе ки вокунишашро бардорад, онро аз даст медиҳад.',
  'Apagar o painel': 'Нест кардани панел',
  'Escolha os seus cargos reagindo aqui embaixo!': 'Нақшҳои худро бо вокуниш дар поён интихоб кунед!',
  'Texto do painel': 'Матни панел',
