  'Publicar o painel': 'Нашр кардани панел',
  'Quais jogos a turma joga, com quantas pessoas e quantas partidas vão até o fim. Só contagem: respostas e desenhos não são guardados. Conta a partir de 12/10/2026.': 'Гурӯҳ кадом бозиҳоро мебозад, бо чанд нафар ва чанд даври бозӣ то охир мерасад. Танҳо шумориш: ҷавобҳо ва расмҳо нигоҳ дошта намешаванд. Аз 12.10.2026 ҳисоб карда мешавад.',
