  'O som': 'Садо',
  'A música': 'Суруд',
  'O emoji': 'Эмоҷӣ',
  'O arquivo': 'Файл',
  '{tipo} «{item}» ({onde}) saiu do Syden porque {quem} disse ter os direitos. Se você tinha autorização para publicar, responda aqui contando: a sua resposta vai ser levada em conta. Enquanto isso não ficar claro, fica fora. Os termos explicam como funciona, na seção 4: https://syden.chat/termos.html#direito-autoral': '{tipo} «{item}» ({onde}) аз Syden бардошта шуд, зеро {quem} мегӯяд, ки ҳуқуқҳо ба ӯ тааллуқ доранд. Агар шумо иҷозати нашр доштед, дар ин ҷо ҷавоб диҳед ва нақл кунед: ҷавоби шумо ба назар гирифта мешавад. То вақте ки ин равшан нашавад, он бардошта боқӣ мемонад. Шартҳо дар бахши 4 мефаҳмонанд, ки ин чӣ тавр кор мекунад: https://syden.chat/termos.html#direito-autoral',
  '«{nome}» saiu.': '«{nome}» бардошта шуд.',
  'Saíram junto {n} cópia(s) do mesmo arquivo.': 'Нусхаҳои ҳамон файл, ки якҷоя бардошта шуданд: {n}.',
  'Quem subiu recebeu o aviso numa conversa com você.': 'Шахсе, ки онро бор кардааст, огоҳиро дар сӯҳбат бо шумо гирифт.',
  'Não havia a quem avisar.': 'Касе набуд, ки огоҳ карда шавад.',
  'É a retirada número {n} desta pessoa.': 'Ин бардоштани рақами {n}-и ин шахс аст.',
  'Direito autoral': 'Ҳуқуқи муаллиф',
  'Quem tem o direito escreve para direitos@syden.chat dizendo o que é e onde está. Procure pelo nome, retire, e quem subiu recebe o aviso numa conversa com você, onde pode contestar.': 'Соҳиби ҳуқуқ ба direitos@syden.chat менависад, ки ин чист ва дар куҷост. Аз рӯи ном ҷустуҷӯ кунед, бардоред ва шахсе, ки онро бор кардааст, огоҳиро дар сӯҳбат бо шумо мегирад ва дар он ҷо метавонад эътироз кунад.',
