  'Quem precisa falar com a administração abre um ticket no início da comunidade, com um assunto. Ele vira uma conversa privada em grupo entre essa pessoa e quem administra, e aparece na lista de conversas de vocês.': 'Касе ки бояд бо маъмурият гап занад, дар саҳифаи аввали анҷуман бо мавзӯъ тикет мекушояд. Он ба сӯҳбати гурӯҳии хусусӣ байни он шахс ва идоракунандагон табдил меёбад ва дар рӯйхати сӯҳбатҳои шумо пайдо мешавад.',
