  'Ticket não encontrado.': 'Тикет ёфт нашуд.',
  'Só quem abriu o ticket ou quem administra pode encerrá-lo.': 'Тикетро танҳо касе ки онро кушодааст ё идоракунандаи анҷуман баста метавонад.',
  'Só quem administra a comunidade mexe nos cargos automáticos.': 'Нақшҳои худкорро танҳо идоракунандагони анҷуман тағйир дода метавонанд.',
