  'Abra ele e a sua conta está pronta — é o que garante que você consiga recuperar a senha um dia, se esquecer.': 'Онро кушоед ва ҳисоби шумо омода мешавад — ҳамин кафолат медиҳад, ки агар рӯзе рамзро фаромӯш кунед, онро барқарор карда тавонед.',
  'Não chegou em alguns minutos? Dê uma olhada no spam ou nas promoções. Se não estiver lá, mande de novo.': 'Дар чанд дақиқа нарасид? Ҷузвдони спам ё таблиғотро бинед. Агар он ҷо ҳам набошад, боз фиристед.',
