  'O seu recurso foi recebido em {quando}. Quem cuida do Syden vai ler e responder.': 'Эътирози шумо {quando} қабул шуд. Дастаи Syden онро хонда, ҷавоб медиҳад.',
  'O seu responsável': 'Сарпарасти шумо',
  'O seu tempo de hoje acabou': 'Вақти имрӯзаи шумо тамом шуд',
  'O Syden é para quem tem 13 anos ou mais.': 'Syden барои онҳоест, ки 13 сол ва болотар доранд.',
  'O Syden é para quem tem 13 anos ou mais. Ninguém vê a sua data.': 'Syden барои онҳоест, ки 13 сол ва болотар доранд. Санаи шуморо ҳеҷ кас намебинад.',
  'O Syden passou a pedir a idade de todo mundo, para proteger quem tem menos de 18 anos (a lei do ECA Digital). Ninguém vê a sua data: só a faixa de idade é usada.': 'Syden акнун синну соли ҳамаро мепурсад, то онҳоеро, ки аз 18 сол хурдтаранд, ҳифз кунад (қонуни ECA Digital). Санаи шуморо ҳеҷ кас намебинад: танҳо гурӯҳи синну сол истифода мешавад.',
  'Para quem foi comunicado e o protocolo (ex.: SaferNet 123)': 'Ба кӣ хабар дода шуд ва рақами парванда (масалан: SaferNet 123)',
  'Por segurança, a prévia das transmissões fica fechada para menores de idade.': 'Барои амният, пешнамоиши пахшҳо барои ноболиғон баста аст.',
  'Por segurança, menores de idade conversam no particular só com amigos.': 'Барои амният, ноболиғон танҳо бо дӯстон сӯҳбати хусусӣ мекунанд.',
  'Qual é a sua data de nascimento?': 'Санаи таваллуди шумо кай аст?',
  'Quem muda estas regras é o seu responsável.': 'Ин қоидаҳоро сарпарасти шумо тағйир медиҳад.',
  'Quem tem de 13 a 15 anos usa o Syden com a conta ligada à de um pai, mãe ou responsável. É a lei (ECA Digital), e é para a sua segurança.': 'Онҳое, ки 13–15 сола ҳастанд, Syden-ро бо ҳисобе истифода мебаранд, ки ба ҳисоби падар, модар ё сарпараст пайваст аст. Ин қонун аст (ECA Digital) ва барои амнияти шумост.',
  'Quem tem menos de 18 anos usa o Syden com proteções a mais, e de 13 a 15 anos com a conta ligada à de um responsável (a lei do ECA Digital).': 'Онҳое, ки аз 18 сол хурдтаранд, Syden-ро бо ҳифзи иловагӣ истифода мебаранд, ва 13–15 солаҳо бо ҳисоби пайваст ба ҳисоби сарпараст (қонуни ECA Digital).',
