  'Abre os mini-games para jogar com a turma.': 'Мини-бозиҳоро мекушояд, то бо гурӯҳ бозӣ кунед.',
  'Cada prateleira guarda os canais da comunidade.': 'Ҳар раф каналҳои ҷамоаро нигоҳ медорад.',
  'Onde o coelho do recado espera quem chega.': 'Ҷое, ки харгӯши паёмрасон омадагонро интизор аст.',
  'Alta, para sentar no balcão e conversar.': 'Баланд, барои нишастан дар назди пештахта ва суҳбат.',
  'Uma máquina de música antiga, com luzes que acendem à noite.': 'Мошини мусиқии кӯҳна, бо чароғҳое, ки шаб медурахшанд.',
  'Com caixa de som, pronto para o karaokê.': 'Бо баландгӯяк, барои караоке тайёр.',
  'Redonda, para cartas, tabuleiro e conversa.': 'Гирд, барои қарта, бозиҳои рӯимизӣ ва суҳбат.',
  'De madeira, com o assento estofado.': 'Чӯбин, бо нишастгоҳи мулоим.',
  'Suco, refrigerante e água sempre gelados.': 'Шарбат, нӯшокӣ ва об, ҳамеша хунук.',
  'A cozinha da turma. O botão direito acende e apaga o fogão.': 'Ошхонаи гурӯҳ. Тугмаи рост плитаро даргиронда ва хомӯш мекунад.',
  'Um pufe enorme, para afundar e ficar.': 'Пуфи азим, барои фурӯ рафтан ва мондан.',
  'Pendurado no gancho, esperando a próxima call.': 'Дар қалмоқ овезон, занги навбатиро интизор аст.',
