  'Um pôr do sol sobre os campos.': 'Ғуруби офтоб бар болои киштзорҳо.',
  'Xícaras, potes e garrafas de suco.': 'Пиёлаҳо, зарфҳо ва шишаҳои шарбат.',
  'Potes de biscoito e pipoca para dividir.': 'Зарфҳои печенье ва попкорн барои тақсим кардан.',
  'As taças das vitórias da turma.': 'Ҷомҳои ғалабаҳои гурӯҳ.',
  'Um coelho de neon que brilha no escuro.': 'Харгӯши неонӣ, ки дар торикӣ медурахшад.',
  'Um relógio de madeira para ninguém perder a hora.': 'Соати чӯбин, то ҳеҷ кас вақтро аз даст надиҳад.',
  'Para quem quiser puxar uma música.': 'Барои касе, ки хоҳад сурудеро сар кунад.',
  'Dá no banheiro. Bata antes de entrar.': 'Ба ҳаммом мебарад. Пеш аз даромадан дарро тақ-тақ кун.',
  'O cartaz do karaokê, em três versões: palco, neon e fogo.': 'Плакати караоке, дар се намуд: саҳна, неон ва оташ.',
  'Dois coelhos, um café e a fofoca do dia.': 'Ду харгӯш, як қаҳва ва гапу гапҳои рӯз.',
