  'Não foi possível entrar nesta chamada.': 'Ба ин занг ҳамроҳ шудан имконнопазир буд.',
  'Corrida dos coelhos': 'Пойгаи харгӯшҳо',
  'Horta': 'Боғи сабзавот',
  'Setas para dirigir, Espaço para derrapar e carregar o turbo.': 'Тирчаҳо барои идора, фосила барои лағжидан ва пур кардани турбо.',
  'Seu recorde: {tempo}': 'Рекорди ту: {tempo}',
  'Correr contra': 'Мусобиқа бо',
  'Nenhum amigo correu nesta pista ainda.': 'Ҳоло ягон дӯст дар ин роҳ надавидааст.',
  'Novo recorde!': 'Рекорди нав!',
  'Virar para a esquerda': 'Ба чап гардонидан',
  'Virar para a direita': 'Ба рост гардонидан',
  'Derrapar': 'Лағжидан',
  'Uma corrida de kart. Sozinho, contra o relógio e os fantasmas dos amigos; com a turma, ao vivo, com itens e a Copa da Cenoura.': 'Пойгаи карт. Танҳо, бар зидди вақт ва арвоҳи дӯстон; бо гурӯҳ, мустақим, бо ашёҳо ва Ҷоми Сабзӣ.',
  'Pomar': 'Боғи мева',
  'Copa da Cenoura': 'Ҷоми Сабзӣ',
  'contra {nomes}': 'бар зидди {nomes}',
  'Usar o item': 'Ашёро истифода бар',
  'Olhar para trás': 'Ба қафо нигоҳ кун',
  'Setas para dirigir, Espaço para derrapar, E para usar o item.': 'Тирчаҳо барои идора, фосила барои лағжидан, E барои истифодаи ашё.',
  'Copa da turma': 'Ҷоми гурӯҳ',
  'Copas da Cenoura que a turma correu até o fim, na Corrida dos coelhos.': 'Ҷомҳои Сабзӣ, ки гурӯҳ дар Пойгаи харгӯшҳо то охир давонд.',
  'Bosque': 'Ҷангал',
  'Cânion': 'Дара',
  'Copa do Repolho': 'Ҷоми Карам',
  'Festa dos coelhos': 'Ҷашни харгӯшҳо',
  'Cinco rodadas de jogos rápidos, cada um na própria tela: reflexo, pontaria, memória e olho. Quem for melhor em cada rodada ganha mais pontos.': 'Панҷ даври бозиҳои тез, ҳар кас дар экрани худ: вокуниш, нишонгирӣ, хотира ва чашм. Касе ки дар ҳар давр беҳтар аст, холи бештар мегирад.',
  'Saque rápido': 'Тирпарронии тез',
  'Espere o sinal e aperte o mais rápido que puder. Antes do sinal, está fora.': 'Сигналро интизор шав ва ҳарчи зудтар пахш кун. Пеш аз сигнал — берун мешавӣ.',
  'Medidor de força': 'Қувваченак',
  'Pare a barra o mais perto possível de 100%.': 'Хатро ҳарчи наздиктар ба 100% боздор.',
  'Parar o relógio': 'Соатро боздор',
  'Pare o relógio em 10 segundos exatos. Os números somem depois de 3.': 'Соатро дар маҳз 10 сония боздор. Рақамҳо баъди 3 нопадид мешаванд.',
  'Jogo dos copos': 'Бозии пиёлаҳо',
  'Veja onde fica a cenoura e siga o copo. Acertar mais rápido vale mais.': 'Бубин, ки сабзӣ дар куҷост, ва пиёларо пайгирӣ кун. Зудтар ёфтан арзиши бештар дорад.',
  'Siga o coelho': 'Аз паи харгӯш рав',
  'Repita as setas na ordem. A cada acerto, vem mais uma.': 'Тирчаҳоро бо тартиб такрор кун. Бо ҳар ҷавоби дуруст боз яке илова мешавад.',
  'Tiro ao alvo': 'Тирандозӣ ба ҳадаф',
  'Acerte os alvos que aparecerem. Cada um vale um ponto.': 'Ба ҳадафҳое, ки пайдо мешаванд, зан. Ҳар кадом як хол дорад.',
  'Cedo demais!': 'Хеле барвақт!',
  'Não valeu': 'Ҳисоб нашуд',
  'Sem resposta': 'Ҷавоб нест',
  'Errou': 'Хато',
  'Nenhum troféu ainda. Fique no pódio de um jogo na sala, com a turma.': 'Ҳоло ягон ҷом нест. Дар бозии ҳуҷра бо гурӯҳ ба шоҳсупа баро.',
