  'Desvie das sementes e derrube a praga. O espantalho vem no fim.': 'Аз тухмиҳо гурез ва зараррасонҳоро сарнагун кун. Матарсак дар охир меояд.',
  'Sem vidas: agora é torcer pela esquadrilha.': 'Ҷон намонд: акнун эскадрилияро дастгирӣ кун.',
