  'Você desistiu.': 'Ту таслим шудӣ.',
  'O tempo acabou: ganhou quem tinha mais.': 'Вақт тамом шуд: касе бурд, ки бештар дошт.',
  'A sua Maravilha ficou de pé por 2 minutos.': 'Мӯъҷизаи ту 2 дақиқа сарпо монд.',
  'A Maravilha do computador ficou de pé por 2 minutos.': 'Мӯъҷизаи компютер 2 дақиқа сарпо монд.',
