  'A sua Maravilha está pronta: defenda-a por 2 minutos!': 'Мӯъҷизаи ту омода аст: онро 2 дақиқа ҳимоя кун!',
  'O computador terminou uma Maravilha: derrube-a em 2 minutos!': 'Компютер Мӯъҷизаро тамом кард: онро дар 2 дақиқа вайрон кун!',
  'A sua vila está sob ataque!': 'Ба деҳаи ту ҳамла мекунанд!',
  'Escolher': 'Интихоб',
  'Botão direito: mandar': 'Тугмаи рост: фармон',
  'Mover o mapa': 'Ҷойивазкунии харита',
  'Este jogo não se joga na sala.': 'Ин бозӣ дар ҳуҷра бозӣ карда намешавад.',
  'Ponha os seus navios no mar.': 'Киштиҳоятро ба баҳр гузор.',
  'Esperando {nome} pôr os navios…': 'Интизорем, ки {nome} киштиҳоро гузорад…',
  'Os dois estão pondo os navios…': 'Ҳарду киштиҳояшонро мегузоранд…',
  'Navio de {n} casas': 'Киштии {n}-хона',
  'Seus navios': 'Киштиҳои ту',
  'Escolha um navio e toque no mar. Arraste para mudar de lugar.': 'Киштиро интихоб кун ва ба баҳр ламс кун. Барои ҷойиваз кардан кашола кун.',
  'Sortear a frota': 'Флоти тасодуфӣ',
  'Sua frota já está pronta.': 'Флоти ту аллакай омода аст.',
  'Ponha todos os navios antes.': 'Аввал ҳамаи киштиҳоро гузор.',
  'Escolha um navio.': 'Киштиро интихоб кун.',
  'O navio não cabe aí.': 'Киштӣ он ҷо намеғунҷад.',
  'Os navios não podem encostar um no outro.': 'Киштиҳо набояд ба ҳамдигар расанд.',
  'Minigolfe 3D': 'Миниголфи 3D',
  'Oito buracos em 3D, com rampas, castelo e moinho, todos jogando o mesmo ao mesmo tempo. Arraste para mirar e dar a força, e solte. Ganha quem somar menos tacadas.': 'Ҳашт чуқурча дар 3D, бо нишебиҳо, қалъа ва осиёи бодӣ, ҳама якбора як чуқурчаро бозӣ мекунанд. Барои нишон гирифтан ва қувва додан каш ва раҳо кун. Ғолиб касест, ки дар маҷмӯъ камтарин зарба дорад.',
  'Ver o buraco de cima': 'Чуқурчаро аз боло дидан',
  'Fora da pista! Mais uma tacada.': 'Аз роҳ берун! Боз як зарба.',
  'Arraste para o lado para mirar e para baixo para a força, e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'Барои нишон гирифтан ба паҳлу ва барои қувва ба поён каш ва раҳо кун. Бо клавиатура: тирчаҳо нишон мегиранд ва фосилаи пахшкарда қувва медиҳад.',
  'Futebol dos coelhos': 'Футболи харгӯшҳо',
  'Futebol de campo pequeno, visto de cima. Encoste na bola para conduzir, segure Espaço para chutar mais forte e passe com X. Na sala, os times se completam com robôs.': 'Футбол дар майдони хурд, аз боло. Ба тӯб даст расон, то онро барӣ, фосиларо пахш карда нигоҳ дор, то сахттар занӣ, ва бо X пас деҳ. Дар ҳуҷра дастаҳо бо роботҳо пур карда мешаванд.',
  'Quantos por time?': 'Дар як даста чанд нафар?',
  'Seu time venceu!': 'Дастаи ту ғолиб шуд!',
  'Seu time perdeu.': 'Дастаи ту бохт.',
  'Passe': 'Пас',
  'Chutar': 'Задан',
  'Chutar (segure para mais força)': 'Задан (барои қуввати бештар нигоҳ дор)',
  'Gol!': 'Гол!',
  'Gol contra': 'Гол ба дарвозаи худ',
  'Partida inválida.': 'Бозии нодуруст.',
  'Ninguém para jogar.': 'Касе барои бозӣ нест.',
  'Caça às pragas da horta': 'Шикори зараррасонҳои полиз',
  'Corvos e gafanhotos atacam a horta. Mire e clique para acertar antes que fujam: a munição é contada, e cada onda vem mais rápida. Ganha quem fizer mais pontos.': 'Зоғҳо ва малахҳо ба полиз ҳамла мекунанд. То нагурехтанд, нишон гир ва пахш кун: тир ҳисобшуда аст, ва ҳар мавҷ тезтар меояд. Касе, ки бештар хол гирад, ғолиб мешавад.',
  'Mire e clique nas pragas antes que fujam. Cada tiro gasta uma cenoura.': 'То зараррасонҳо нагурехтанд, нишон гир ва пахш кун. Ҳар тир як сабзиро сарф мекунад.',
  'Munição: {n}': 'Тир: {n}',
