  'Tacadas: {n}': 'Зарбаҳо: {n}',
  'Puxe a bola para trás e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'Тӯбро ба қафо кашу раҳо кун. Бо клавиатура: тирчаҳо нишон мегиранд ва фосилаи пахшкарда қувва медиҳад.',
  'Na água! Mais uma tacada.': 'Ба об! Боз як зарба.',
