  'Para a direita': 'Ба рост',
  'Setas para correr, Espaço para pular (segure para ir mais alto).': 'Тирчаҳо барои давидан, фосила барои ҷаҳидан (барои баландтар рафтан пахш карда нигоҳ дор).',
  'Nenhum amigo jogou esta fase ainda.': 'Ҳоло ягон дӯст ин марҳиларо набозидааст.',
  'Chuva na horta: todo mundo ganha {n} cenouras.': 'Борон дар полиз: ҳама {n} сабзӣ мегиранд.',
  '{nome} achou {n} cenouras escondidas.': '{nome} {n} сабзии пинҳонро ёфт.',
  '{nome} trocou de lugar com {outro}.': '{nome} бо {outro} ҷой иваз кард.',
  'Faltou gente: a partida acabou antes do fim, sem troféus.': 'Одам нарасид: бозӣ пеш аз охир тамом шуд, бе ҷоизаҳо.',
  'Saiu antes do fim': 'Пеш аз охир баромад',
  'Jogar o dado': 'Мӯҳра партофтан',
  '{nome} comprou a cenoura dourada!': '{nome} сабзии тиллоиро харид!',
  'Comprar a cenoura dourada por {preco} cenouras?': 'Сабзии тиллоиро бо {preco} сабзӣ мехарӣ?',
  'Comprar': 'Харидан',
  '{nome} chegou à cenoura dourada.': '{nome} ба сабзии тиллоӣ расид.',
  'Quantas rodadas?': 'Чанд давр?',
  'Os coelhos defendem a horta de raposas, corvos e um texugo. Andem juntos, batam em combo e cuidem uns dos outros: de 1 a 4 pessoas.': 'Харгӯшҳо полизро аз рӯбоҳҳо, зоғҳо ва як гӯрков ҳимоя мекунанд. Якҷоя равед, бо комбо занед ва аз ҳамдигар хабар гиред: аз 1 то 4 нафар.',
  'Pulo do coelho': 'Ҷаҳиши харгӯш',
  'Uma corrida de plataforma: correr, pular e não cair. Sozinho, contra o relógio e os fantasmas dos amigos; com a turma, ao vivo, numa fase ou nas três.': 'Пойга дар платформаҳо: тоз, ҷаҳ ва наафт. Танҳо, бар зидди вақт ва арвоҳи дӯстон; бо гурӯҳ, мустақим, дар як марҳила ё дар ҳар сеаш.',
  'Troque dois legumes vizinhos para juntar três ou mais iguais. A pilha sobe sem parar: não deixe chegar ao topo. Com a turma, as cadeias e os combos mandam caixotes para os outros.': 'Ду сабзавоти ҳамсояро иваз кун, то се ё зиёда якхеларо ҷамъ кунӣ. Тӯда бетанаффус боло меравад: нагузор, ки ба боло расад. Бо гурӯҳ, занҷираҳо ва комбоҳо ба дигарон қуттӣ мефиристанд.',
  'Seis buracos de minigolfe, todos jogando o mesmo ao mesmo tempo. Puxe a bola para trás e solte para dar a tacada. Ganha quem somar menos tacadas.': 'Шаш сӯрохии миниголф, ҳама як вақт якхеларо мебозанд. Тӯбро ба қафо кашу раҳо кун, то зарба занӣ. Касе ғолиб мешавад, ки дар маҷмӯъ камтарин зарба дорад.',
  'Cada um joga o dado na sua vez e anda pela horta. Junte cenouras para comprar a cenoura dourada, e depois de cada rodada a turma joga um microjogo. Ganha quem tiver mais cenouras douradas.': 'Ҳар кас дар навбати худ мӯҳра мепартояд ва дар полиз роҳ меравад. Сабзӣ ҷамъ кун, то сабзии тиллоиро харӣ, ва баъди ҳар давр гурӯҳ як бозии хурд мебозад. Касе ғолиб мешавад, ки бештар сабзии тиллоӣ дорад.',
  'Os pódios e as conquistas da turma': 'Шоҳсупаҳо ва дастовардҳои гурӯҳ',
