    'Дар пойтахтҳои Бразилия гардед, шаҳр харед ва аз касоне, ки дар онҳо меистанд, иҷора гиред. Бо тамоми минтақа бино сохтан мумкин аст. Мубодила кунед, дар музоядаҳо рақобат кунед ва бепул намонед.',
