  'Batalha naval': 'Ҷанги баҳрӣ',
  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': 'Доминои маъмулӣ, барои 2–4 нафар (бо 4 нафар, ҷуфт-ҷуфт). Сангҳоро ба нӯгҳои занҷир пайваст кунед, ва касе ки аввал тамом кунад, холҳои дасти дигаронро мегирад.',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': 'Трукои паулиста, бо корти кушода ва козирҳо, 2 нафар ё 4 нафар ҷуфт-ҷуфт. Труко эълон кунед, то шаш, нӯҳ ва дувоздаҳ баланд кунед ё гурезед. Касе ки 12 хол ҷамъ кунад, ғолиб аст.',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': 'Шашкаи бразилӣ: задан ҳатмист, ба пеш ва ба қафо, ва дама тамоми диагоналро мегузарад. Ҳуҷра тамошо мекунад.',
  'Cada um esconde a sua frota e atira no mar do outro. Acertou, atira de novo. Vence quem afundar a frota inteira primeiro. A sala assiste.': 'Ҳар кас флоти худро пинҳон карда, ба баҳри дигаре тир мепартояд. Агар занед, боз тир мепартоед. Касе ки аввал тамоми флотро ғарқ кунад, ғолиб аст. Ҳуҷра тамошо мекунад.',
