  Torre: 'Рух',
  Bispo: 'Фил',
  'Cozinha da toca': 'Ошхонаи лона',
  'Pegue os ingredientes nos caixotes, pique na tábua, cozinhe no fogão e no forno sem queimar, monte no prato e entregue na janela. Todos recebem os mesmos pedidos: ganha quem entregar mais pratos em 3 minutos.': 'Масолеҳро аз қуттиҳо гиред, дар тахта майда кунед, бе сӯзондан дар оташдон ва танӯр пазед, дар табақ гузоред ва дар тиреза супоред. Ҳама фармоишҳои якхела мегиранд: касе ки дар 3 дақиқа табақҳои бештар супорад, ғолиб мешавад.',
  'Pegar ou largar': 'Гирифтан ё гузоштан',
  'Este jogo precisa de gráficos 3D, que não abriram neste aparelho.': 'Ин бозӣ графикаи 3D мехоҳад, ки дар ин дастгоҳ кушода нашуд.',
