  "Diagnóstico do host": "Ташхиси хост",
  "Registros limitados de Docker, SSH, logind e kernel dos três boots mais recentes. Podem conter endereços IP.": "Сабтҳои маҳдуди Docker, SSH, logind ва ядро аз се оғози охирин. Метавонанд суроғаҳои IP дошта бошанд.",
  "Atualizar diagnóstico": "Навсозии ташхис",
  "Ainda não há snapshot. Ele será coletado na próxima abertura do cofre.": "Ҳоло акс нест. Он дафъаи дигар ҳангоми кушодани сейф ҷамъ мешавад.",
  "Coletado em {data}": "Ҷамъшуда {data}",
  "Medido pela {nome}": "Ченкардаи {nome}",
  "Os mesmos números do painel do provedor. Inclui o disco, que o servidor não mede sozinho.": "Ҳамон рақамҳои панели провайдер. Дискро ҳам дар бар мегирад, ки сервер худаш чен намекунад.",
  "Ações no servidor": "Амалҳо дар сервер",
  "O histórico da Hetzner: ligar, desligar e reiniciar, pelo painel ou pela API. Uma queda sem ação aqui não foi comandada por esses caminhos.": "Таърихи Hetzner: фаъол, хомӯш ва аз нав оғоз кардан аз панел ё тавассути API. Қатъе, ки дар ин ҷо амал надорад, бо ин роҳҳо ба вуҷуд наомадааст.",
