  'Desfocado': "Хира кардан",
  'Desfoca, apaga ou troca o que aparece atrás de você. A imagem da câmera não sai do computador para isso.': "Он чиро, ки дар паси ту намоён аст, хира мекунад, пок мекунад ё иваз мекунад. Барои ин тасвири камера аз компютери ту берун намеравад.",
  // A transmissão personalizada (16/11/2026)
  'Nativa': "Аслӣ",
  'Resolução': "Ҳалнокӣ",
  'Quadros por segundo': "Кадр дар сония",
  'Para quando a escolha automática errar: a resolução e os quadros ficam os que você escolher, do começo ao fim da transmissão.': "Барои вақте ки интихоби худкор хато мекунад: ҳалнокӣ ва кадрҳо аз аввал то охири пахш ҳамон тавре мемонанд, ки ту интихоб мекунӣ.",
  // O Syden Broadcast (16/11/2026)
  'Os efeitos de voz e de câmera feitos no seu computador, sem enviar nada a um servidor.': "Эффектҳои овоз ва камера, ки дар компютери ту сохта мешаванд, бе фиристодани чизе ба сервер.",
  // A Masmorra da Toca (16/11/2026)
  'Masmorra da Toca': "Зиндони лона",
  'Atravessem juntos a toca do rei-cogumelo: salas cheias de bichos, um baú com a cenoura que vai e volta, botões que pedem dois ao mesmo tempo e a porta trancada. De 1 a 4 pessoas.': "Аз лонаи шоҳи занбӯруғ якҷоя гузаред: ҳуҷраҳои пур аз ҷонварон, сандуқе бо сабзие, ки меравад ва бармегардад, тугмаҳое, ки якбора ду касро мехоҳанд, ва дари қулфшуда. Аз 1 то 4 нафар.",
  // O Ringue da Toca (16/11/2026)
  'Ringue da Toca': "Ринги лона",
  'Boxe de reflexo contra três adversários do computador. Leia o aviso de cada golpe, esquive ou defenda e bata na brecha. Bater quando a luva brilha enche a estrela do soco forte.': "Бокси вокуниш бар зидди се рақиби компютер. Нишонаи ҳар зарбаро хон, канора гир ё муҳофизат кун ва ба холигӣ зан. Зарба ҳангоми дурахшидани дастпӯшак ситораи зарбаи пурзӯрро пур мекунад.",
  'Esquivar': "Канора гир",
  'Abaixar e defender': "Хам шав ва муҳофизат кун",
  'Socar': "Зан",
  'Soco forte': "Зарбаи пурзӯр",
  'Aperte os socos para levantar!': "Барои хестан зарбаҳоро пахш кун!",
  'Lutas vencidas: {n}': "Набардҳои бурда: {n}",
  'Nocaute!': "Нокаут!",
  // A Rota Estelar (16/11/2026)
  'Rota Estelar': "Роҳи ситораҳо",
  'Coelhos em naves pela superfície de um planeta e pelo espaço: atire, segure o tiro para travar a mira, gire para desviar dos tiros e escolha o caminho na bifurcação. A turma voa a mesma rota, e o chefe espera no fim.': "Харгӯшҳо дар киштиҳои кайҳонӣ болои сатҳи сайёра ва дар кайҳон: тир холӣ кун, барои қуфл кардани ҳадаф тирро пахш карда нигоҳ дор, барои гардонидани тирҳо чарх зан ва дар дуроҳа роҳро интихоб кун. Гурӯҳ дар як роҳ парвоз мекунад ва дар охир сардор интизор аст.",
  'Pirueta': "Чархзанӣ",
  'Segure para travar a mira': "Барои қуфл пахш карда нигоҳ дор",
  // O Comando Cenoura (16/11/2026)
  'Comando Cenoura': "Командоси сабзӣ",
  'Correr e atirar com a turma: o lança-cenouras mira em oito direções, a granada abre caminho e quem solta os coelhinhos presos ganha reforço. O dragão espera no fim: de 1 a 4 pessoas.': "Бо гурӯҳ давида тир парон: сабзиандоз ба ҳашт самт нишон мегирад, норинҷак роҳ мекушояд ва касе, ки харгӯшчаҳои дар қафасро озод кунад, қувваи иловагӣ мегирад. Дар охир аждаҳо интизор аст: аз 1 то 4 нафар.",
  'Andar e mirar': "Рафтан ва нишон гирифтан",
  'Granada': "Норинҷак",
  // O Pinball da Horta (16/11/2026)
  'Pinball da Horta': "Пинболи боғча",
  'Uma mesa de pinball na horta: segure a mola, rebata nos repolhos e derrube as três cenouras para acender a toca do coelho, que solta mais uma bola. Três bolas, e sacudir demais trava a mesa.': "Мизи пинбол дар боғи сабзавот: пружинаро нигоҳ дор, аз карамҳо ҷаҳон ва се сабзиро афтон, то лонаи харгӯш равшан шавад ва боз як тӯб барорад. Се тӯб, ва аз ҳад зиёд ҷунбондан мизро қулф мекунад.",
  'Palhetas': "Зарбзанакҳо",
  'Mola': "Пружина",
  'Sacudir': "Ҷунбондан",
  'Bola salva!': "Тӯб наҷот ёфт!",
  'Multibola!': "Тӯбҳои зиёд!",
