  'Desafios de voo: asa-delta, mochila a jato e paraquedas. Passe pelos anéis e pouse no alvo, perto do centro e de leve.': 'Озмоишҳои парвоз: дельтаплан, ҷузвдони реактивӣ ва парашют. Аз ҳалқаҳо гузар ва ба ҳадаф, наздики марказ ва нарм фуруд ой.',
