  // Lendas da Toca (16/11/2026)
  'Lendas da Toca': "Афсонаҳои лона",
  'Um RPG de turnos curto: cada um controla um herói da turma. Escolham juntos, combinem ataques e vençam o dragão do castelo.': "RPG-и кӯтоҳи навбатӣ: ҳар кас як қаҳрамони гурӯҳро идора мекунад. Якҷоя интихоб кунед, ҳамлаҳоро омехта кунед ва аждаҳои қалъаро шикаст диҳед.",
