  'Combo': "Комбо",
  'Dois ou mais no Combo atacam juntos.': "Ду ё зиёда дар Комбо якҷоя ҳамла мекунанд.",
  'Equipar': "Пӯшидан",
  'Deixar': "Мондан",
  // Bichos da Toca (16/11/2026)
  'Bichos da Toca': "Ҳайвонҳои лона",
  'Ande pelo campo, faça amizade com os bichos do mato usando uma cenoura e monte uma equipe de até seis. Vença o desafio da casa azul e, na sala, lute com a equipe de um amigo.': "Дар саҳроҳо гашт зан, бо ҳайвонҳои алафи баланд бо сабзӣ дӯст шав ва дастаи то шаш нафар ташкил кун. Озмоиши хонаи кабудро бурд кун ва дар утоқ бо дастаи дӯстат ҷанг кун.",
  'Gota': "Қатра",
