  "{nome} terminou uma Maravilha: defenda-a por 2 minutos!": "{nome} Мӯъҷизаро сохт: онро 2 дақиқа ҳимоя кун!",
  "{nome} terminou uma Maravilha.": "{nome} Мӯъҷизаро сохт.",
  "A Maravilha da outra equipe ficou de pé por 2 minutos.": "Мӯъҷизаи дастаи дигар 2 дақиқа сарпо монд.",
