  "Duas equipes de dois. Os robôs completam os lugares que faltam.": "Ду дастаи дунафара. Ҷойҳои холиро роботҳо пур мекунанд.",
  "Gênero": "Ҷинс",
  "Levadiça": "Пули бардоштанӣ",
  'Nenhuma conversa ainda. Toque em alguém na lista de pessoas da comunidade e escolha "Enviar mensagem".': "Ҳоло ягон сӯҳбат нест. Касеро дар рӯйхати одамони анҷуман пахш кун ва \"Фиристодани паём\"-ро интихоб кун.",
  "Varia": "Гуногун",
  "Vitória de {nomes}": "Ғалабаи {nomes}",
  "Vocês derrubaram os dois centros da vila da outra equipe.": "Шумо ҳар ду маркази деҳаи дастаи дигарро вайрон кардед.",
  // Os mini-games e as insígnias (19/11/2026)
  "A cidade que ninguém compra vai a leilão. Hipotecar uma cidade dá dinheiro, mas ela não cobra aluguel.": "Шаҳре, ки касе намехарад, ба музояда меравад. Ба гарав гузоштани шаҳр пул медиҳад, аммо он иҷора намегирад.",
  "A dica acende a peça que move. O problema com dica não pontua; na corrida, ela tira 10 segundos.": "Маслиҳат донаеро, ки бояд ҳаракат кунад, равшан мекунад. Масъала бо маслиҳат хол намедиҳад; дар пойга маслиҳат 10 сония мегирад.",
  "A manilha é o valor seguinte ao da vira e ganha de todas. Entre elas: ouros, espadas, copas e paus, o zap.": "Козир арзиши баъд аз корти кушода аст ва ҳамаро мебарад. Дар байни худ: ♦, ♠, ♥ ва ♣, яъне зап.",
  "A última nave de cada volta sai.": "Киштии охирини ҳар давр аз пойга мебарояд.",
  "Abaixar": "Хам шав",
  "Acertos em sequência: {n}": "Пай дар пай ҳалшуда: {n}",
  "Ande pelo dado e compre a capital onde parar. Quem para na cidade de outro paga aluguel.": "Бо мӯҳра қадам зан ва пойтахтеро, ки дар он истодӣ, бихар. Касе ки дар шаҳри дигарон истад, иҷора медиҳад.",
  "Cada linha, coluna e bloco de 3 × 3 tem os números de 1 a 9, sem repetir.": "Дар ҳар сатр, сутун ва блоки 3 × 3 рақамҳои аз 1 то 9 бе такрор ҳастанд.",
  "Cada um recebe 3 cartas. Leva a mão quem ganhar 2 das 3 rodadas.": "Ҳар кас 3 корт мегирад. Дастро касе мегирад, ки 2-то аз 3 даврро бибарад.",
  "Campeonato": "Чемпионат",
  "Com 11 pontos, a dupla vê as cartas e decide se joga a mão de onze. Vence quem chegar a 12.": "Бо 11 хол ҷуфт кортҳоро мебинад ва қарор медиҳад, ки дасти ёздаҳро бозӣ кунад ё не. Касе ки ба 12 расад, ғолиб аст.",
  "Com a região inteira, construa até 4 prédios: o aluguel sobe a cada um.": "Бо тамоми минтақа то 4 бино соз: бо ҳар кадом иҷора меафзояд.",
  "Com estrelas, o soco forte (★) gasta todas de uma vez e dói mais.": "Зарбаи пурзӯр (★) ҳамаи ситораҳоро якбора сарф мекунад ва сахттар мезанад.",
  "Dica": "Маслиҳат",
  "Dica: este problema não pontua": "Маслиҳат: ин масъала хол намедиҳад",
  "Dica: tira 10 segundos": "Маслиҳат: минус 10 сония",
  "Eliminação": "Хориҷкунӣ",
  "Encoste uma pedra numa ponta da mesa com o mesmo número.": "Ба як нӯги миз санги ҳамон рақамро пайваст кун.",
  "Escolha a casa e depois o número. O lápis anota só para você.": "Аввал хона, баъд рақамро интихоб кун. Қайдҳои қаламро танҳо ту мебинӣ.",
  "Esquive do golpe e soque logo depois: é o contra-ataque, e vale estrela.": "Аз зарба канор гир ва фавран зан: ин ҳамлаи ҷавобӣ аст ва ситора медиҳад.",
  "Fora da corrida na volta {n}.": "Дар даври {n} берун аз пойга.",
  "Força das cartas": "Қувваи кортҳо",
  "Ganha o maior patrimônio no fim das rodadas, ou quem sobrar.": "Дар охири даврҳо бузургтарин дороӣ ё касе ки охирин монад, ғолиб мешавад.",
  "Iniciante": "Навомӯз",
  "Mestre": "Устод",
  "Na sequência, cada acerto traz um problema mais difícil, e o primeiro erro acaba.": "Дар силсила ҳар ҷавоби дуруст масъалаи душвортар меорад, ва хатои аввал онро тамом мекунад.",
  "O número pequeno no botão diz quantos ainda faltam.": "Рақами хурд дар тугма нишон медиҳад, ки боз чандто мондааст.",
  "Os cinco traçados seguidos contra o computador, com pontos.": "Панҷ роҳ пай дар пай бар зидди компютер, бо хол.",
  "Peça truco e a mão vale 3. Quem responde aceita, corre ou aumenta para 6, 9 ou 12.": "Труко эълон кун ва даст 3 меарзад. Ҷавобдиҳанда қабул мекунад, мегурезад ё то 6, 9 ё 12 баланд мекунад.",
  "Quem bate fica sem pedras e leva os pontos das mãos dos outros. Trancado, leva quem tem menos pontos na mão.": "Касе ки тамом кунад, бе санг мемонад ва холҳои дасти дигаронро мегирад. Агар бозӣ баста шавад, касе мегирад, ки дар даст камтарин хол дорад.",
  "Sem pedra que sirva, compre. Sem nada para comprar, a vez passa.": "Санги мувофиқ набошад, санг гир. Чизе барои гирифтан набошад, навбат мегузарад.",
  "Sequência": "Силсила",
  "Soque quando a luva brilhar: o golpe para e você ganha uma estrela.": "Вақте ки дастпӯшак медурахшад, зан: зарба қатъ мешавад ва ту ситора мегирӣ.",
  "Treino livre": "Машқи озод",
