  "A turma fez uma vaquinha: cada um te dá {valor}.": "Гурӯҳ пул ҷамъ кард: ҳар кас ба шумо {valor} медиҳад.",
  "Aceitar que não vale": "Қабул кардан, ки ҳисоб нест",
  "Achou um atalho: avance 5 casas.": "Роҳи кӯтоҳ ёфтед: 5 хона пеш равед.",
  "Alta temporada em {lugares}: os aluguéis dobram por uma rodada.": "Мавсими авҷ ({lugares}): иҷорапулӣ барои як давр ду баробар мешавад.",
  "As duas diagonais também têm os números de 1 a 9.": "Ҳар ду диагонал низ рақамҳои 1 то 9-ро доранд.",
  "As escuras não fazem dois três abertos de uma vez": "Сиёҳҳо якбора ду сегонаи кушод намесозанд",
  "As escuras não podem fazer dois três abertos de uma vez.": "Сиёҳҳо наметавонанд якбора ду сегонаи кушод созанд.",
  "Baixa temporada em {lugares}: os aluguéis caem pela metade por uma rodada.": "Мавсими суст ({lugares}): иҷорапулӣ барои як давр ду баробар кам мешавад.",
  "Batidas especiais: carroça e lá-e-ló valem o dobro": "Бастанҳои махсус: дубл ва санге, ки ба ҳар ду канор мувофиқ аст, ду баробар арзиш доранд",
  "Brasil inteiro": "Тамоми Бразилия",
  "Captura: cercar duas pedras do outro tira as duas": "Асир кардан: иҳота кардани ду санги ҳариф ҳар дуро мегирад",
  "Carroça!": "Дубл!",
  "Cenoura dourada": "Сабзии тиллоӣ",
  "Chá forte": "Чойи ғализ",
  "Chegou o IPTU: pague {valor} por cidade sua.": "Андози амвол омад: барои ҳар шаҳри худ {valor} пардозед.",
  "Chuva de estrelas": "Борони ситораҳо",
  "Com a captura, cercar duas pedras do outro entre duas suas tira as duas; cinco capturas também vencem.": "Бо асир кардан: ду санги ҳариф, ки байни ду санги шумо монад, ҳар ду гирифта мешаванд; панҷ асир кардан низ ғалаба аст.",
  "Com a restrição 3-3, as escuras não podem fazer dois três abertos de uma vez.": "Бо маҳдудияти 3-3 сиёҳҳо наметавонанд якбора ду сегонаи кушод созанд.",
  "Com as batidas especiais, bater com carroça ou com a pedra que serve nas duas pontas vale o dobro; a carroça nas duas pontas, o quádruplo.": "Бо бастанҳои махсус бастан бо дубл ё бо санге, ки ба ҳар ду канор мувофиқ аст, ду баробар арзиш дорад; дубле, ки ба ҳар ду канор мувофиқ аст, чор баробар.",
