  "Saara": "Саҳрои Кабир",
  "Sai um animal secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a classe, a dieta, onde ele vive e o peso. Quem acertar com menos chutes ganha mais pontos.": "Як ҳайвони пинҳонӣ интихоб мешавад ва ҳар кас ҳайвонҳои дигарро тахмин мезанад. Ҳар тахмин нишон медиҳад, ки чӣ бо пинҳонӣ мувофиқ аст: синф, ғизо, макони зист ва вазн. Касе ки бо тахминҳои камтар ёбад, холи бештар мегирад.",
  "Sai um dinossauro secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: o período, a dieta, o grupo, o comprimento e onde ele foi achado. Quem acertar com menos chutes ganha mais pontos.": "Як динозаври пинҳонӣ интихоб мешавад ва ҳар кас динозаврҳои дигарро тахмин мезанад. Ҳар тахмин нишон медиҳад, ки чӣ бо пинҳонӣ мувофиқ аст: давра, ғизо, гурӯҳ, дарозӣ ва ҷое ки ёфт шудааст. Касе ки бо тахминҳои камтар ёбад, холи бештар мегирад.",
  "Sai um elemento químico secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a família, o estado físico, o período, o grupo e o número atômico. Quem acertar com menos chutes ganha mais pontos.": "Як унсури кимиёвии пинҳонӣ интихоб мешавад ва ҳар кас унсурҳои дигарро тахмин мезанад. Ҳар тахмин нишон медиҳад, ки чӣ бо пинҳонӣ мувофиқ аст: оила, ҳолати агрегатӣ, давра, гурӯҳ ва рақами атомӣ. Касе ки бо тахминҳои камтар ёбад, холи бештар мегирад.",
  "Sai um estado secreto do Brasil, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a população, a área, o litoral e a fronteira com outro país. Quem acertar com menos chutes ganha mais pontos.": "Як иёлати пинҳонии Бразилия интихоб мешавад ва ҳар кас иёлатҳои дигарро тахмин мезанад. Ҳар тахмин масофа ва самтро то иёлати пинҳонӣ, минтақа, аҳолӣ, масоҳат, соҳил ва сарҳад бо кишвари дигарро нишон медиҳад. Касе ки бо тахминҳои камтар ёбад, холи бештар мегирад.",
